export const P = Object.fromEntries(PARAMS.map((p) => [p.sym.slice(2), p.id]));
// 16 bits on the wire (params.c pq / pdq)
export function quant(p, v) {
  v = Math.min(p.max, Math.max(p.min, v));
  if (p.kind !== 'cont') return Math.round(v - p.min);
  return Math.round(((v - p.min) / (p.max - p.min)) * 65535);
}
export function dequant(p, q) {
  if (p.kind !== 'cont') return Math.min(p.max, Math.max(p.min, p.min + q));
  return p.min + ((p.max - p.min) * q) / 65535;
}
